import{_ as e,c as l,ag as i,o as t}from"./chunks/framework.BxW8Wou5.js";const c=JSON.parse('{"title":"8、IP 地址和子网划分","description":"","frontmatter":{},"headers":[],"relativePath":"ruankao/软件设计师/第13章 - 计算机网络/8.IP地址和子网划分.md","filePath":"ruankao/软件设计师/第13章 - 计算机网络/8.IP地址和子网划分.md","lastUpdated":1762439185000}'),r={name:"ruankao/软件设计师/第13章 - 计算机网络/8.IP地址和子网划分.md"};function o(n,a,_,d,s,h){return t(),l("div",null,a[0]||(a[0]=[i('<h1 id="_8、ip-地址和子网划分" tabindex="-1">8、IP 地址和子网划分 <a class="header-anchor" href="#_8、ip-地址和子网划分" aria-label="Permalink to &quot;8、IP 地址和子网划分&quot;">​</a></h1><h2 id="ip-地址" tabindex="-1">IP 地址 <a class="header-anchor" href="#ip-地址" aria-label="Permalink to &quot;IP 地址&quot;">​</a></h2><ul><li>由 4 个小于 256 的数字组成</li><li>有二进制和十进制两种格式</li></ul><h3 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to &quot;分类&quot;">​</a></h3><p>全 0 代表网络，全 1 代表广播</p><ul><li>A 类：0 - 127，8 位网络地址，24 位主机地址</li><li>B 类 128 - 191，16 位网络地址，16 位主机地址</li><li>C 类 192 - 223，24 为符网络地址，8 位主机地址</li></ul><h3 id="子网划分" tabindex="-1">子网划分 <a class="header-anchor" href="#子网划分" aria-label="Permalink to &quot;子网划分&quot;">​</a></h3><ul><li>根据原子网掩码判断借了多少个子网号</li><li>划分数为 2 的借位数次方</li></ul><h2 id="网络地址" tabindex="-1">网络地址 <a class="header-anchor" href="#网络地址" aria-label="Permalink to &quot;网络地址&quot;">​</a></h2><ul><li>分为网络地址和主机地址</li><li>一共 32 位</li><li>可用主机地址：为 2 的主机地址位数次方 - 2</li></ul>',10)]))}const p=e(r,[["render",o]]);export{c as __pageData,p as default};
